package com.ecole.gestion_scolaire.student.controller;
import com.ecole.gestion_scolaire.student.dto.*; import com.ecole.gestion_scolaire.student.service.AuthorizedPickupPersonService; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/students/{studentId}/authorized-pickups") public class AuthorizedPickupPersonController{private final AuthorizedPickupPersonService service;public AuthorizedPickupPersonController(AuthorizedPickupPersonService s){service=s;} @GetMapping @PreAuthorize("hasAuthority('PERSONNE_AUTORISEE_CONSULTER')") public List<AuthorizedPickupPersonResponse> all(@PathVariable Long studentId){return service.findByStudent(studentId);} @PostMapping @PreAuthorize("hasAuthority('PERSONNE_AUTORISEE_GERER')") public ResponseEntity<AuthorizedPickupPersonResponse> create(@PathVariable Long studentId,@Valid @RequestBody AuthorizedPickupPersonRequest r){return ResponseEntity.status(HttpStatus.CREATED).body(service.create(studentId,r));} @PutMapping("/{id}") @PreAuthorize("hasAuthority('PERSONNE_AUTORISEE_GERER')") public AuthorizedPickupPersonResponse update(@PathVariable Long studentId,@PathVariable Long id,@Valid @RequestBody AuthorizedPickupPersonRequest r){return service.update(id,r);}}
